1	import { create } from "zustand";
2	import { Activity, mapActivityFromDB } from "@/types/activity";
3	import { TreeService } from "@/services/TreeService";
4	import { activeTreeId, isActiveTree } from "@/hooks/useTreeStore";
5	
6	export const ACTIVITY_PAGE_SIZES = [10, 25, 50, 100] as const;
7	const DEFAULT_PAGE_SIZE = 25;
8	
9	type FilterKey = "filterActor" | "filterAction" | "filterTargetType";
10	
11	interface ActivityState {
12	  activities: Activity[];
13	  actors: string[];
14	  total: number;
15	  page: number;
16	  pageSize: number;
17	  filterActor: string;
18	  filterAction: string;
19	  filterTargetType: string;
20	  initialized: boolean;
21	  loading: boolean;
22	  error: string | null;
23	  load: (treeId: string, page: number) => Promise<void>;
24	  refreshActivity: (treeId?: string) => Promise<void>;
25	  setPage: (page: number, treeId?: string) => Promise<void>;
26	  setPageSize: (size: number, treeId?: string) => Promise<void>;
27	  setFilter: (key: FilterKey, val: string, treeId?: string) => Promise<void>;
28	  clearFilters: (treeId?: string) => Promise<void>;
29	  retry: (treeId?: string) => Promise<void>;
30	  clear: () => void;
31	}
32	
33	const initialState = {
34	  activities: [] as Activity[],
35	  actors: [] as string[],
36	  total: 0,
37	  page: 0,
38	  pageSize: DEFAULT_PAGE_SIZE,
39	  filterActor: "",
40	  filterAction: "",
41	  filterTargetType: "",
42	  initialized: false,
43	  loading: false,
44	  error: null as string | null,
45	};
46	
47	export const useActivityStore = create<ActivityState>((set, get) => {
48	  // Monotonic request counter guarding against out-of-order responses. When the
49	  // user changes page, page size, or a filter faster than the server responds,
50	  // several loads for the same tree are in flight at once; only the most recent
51	  // one may write results, loading, or error into the store. Kept in the store
52	  // closure (not in state) so bumping it never triggers a re-render.
53	  let requestId = 0;
54	
55	  return {
56	    ...initialState,
57	
58	    load: async (treeId: string, page: number) => {
59	      const { pageSize, filterActor, filterAction, filterTargetType } = get();
60	      const reqId = ++requestId;
61	      set({ loading: true, error: null });
62	      try {
63	        const result = await TreeService.getActivity(treeId, {
64	          offset: page * pageSize,
65	          limit: pageSize,
66	          actor: filterActor || undefined,
67	          action: filterAction || undefined,
68	          target_type: filterTargetType || undefined,
69	        });
70	        // Drop the response if a newer request superseded it, or the tree
71	        // switched mid-flight — stale data must never overwrite newer state.
72	        if (reqId !== requestId || !isActiveTree(treeId)) return;
73	        set({
74	          activities: result.entries.map(mapActivityFromDB),
75	          actors: result.actors,
76	          total: result.total,
77	          page,
78	          initialized: true,
79	          loading: false,
80	        });
81	      } catch (error) {
82	        if (reqId !== requestId || !isActiveTree(treeId)) return;
83	        set({ loading: false, error: String(error) });
84	      }
85	    },
86	
87	    refreshActivity: async (treeId = activeTreeId()) => {
88	      if (!treeId) {
89	        set({ activities: [], actors: [], total: 0, initialized: false });
90	        return;
91	      }
92	      await get().load(treeId, get().page);
93	    },
94	
95	    setPage: async (page, treeId = activeTreeId()) => {
96	      if (!treeId) return;
97	      await get().load(treeId, page);
98	    },
99	
100	    setPageSize: async (size, treeId = activeTreeId()) => {
101	      set({ pageSize: size });
102	      if (!treeId) return;
103	      await get().load(treeId, 0);
104	    },
105	
106	    setFilter: async (key, val, treeId = activeTreeId()) => {
107	      set({ [key]: val });
108	      if (!treeId) return;
109	      await get().load(treeId, 0);
110	    },
111	
112	    clearFilters: async (treeId = activeTreeId()) => {
113	      set({ filterActor: "", filterAction: "", filterTargetType: "" });
114	      if (!treeId) return;
115	      await get().load(treeId, 0);
116	    },
117	
118	    retry: async (treeId = activeTreeId()) => {
119	      if (!treeId) return;
120	      await get().load(treeId, get().page);
121	    },
122	
123	    // Invalidate any in-flight request so its late response can't repopulate a
124	    // store that has since been reset (e.g. tree switch or logout).
125	    clear: () => {
126	      requestId++;
127	      set({ ...initialState });
128	    },
129	  };
130	});
