14	export interface ActivityDB {
15	  id: string;
16	  tree_id: string;
17	  actor_id: string | null;
18	  actor_username: string | null;
19	  action: string;
20	  target_type: string;
21	  target_id: string | null;
22	  target_label: string | null;
23	  created_at: string;
24	  details?: string | null;
25	}
26	
27	export interface ActivityPageDB {
28	  entries: ActivityDB[];
29	  total: number;
30	  actors: string[];
31	}
32	
33	export function mapActivityFromDB(row: ActivityDB): Activity {
34	  let details: Record<string, unknown> | null = null;
35	  if (row.details) {
36	    try {
37	      details = JSON.parse(row.details) as Record<string, unknown>;
38	    } catch {
39	      details = null;
40	    }
41	  }
42	  return {
43	    id: row.id,
44	    treeId: row.tree_id,
45	    actorId: row.actor_id,
46	    actorUsername: row.actor_username,
47	    action: row.action,
48	    targetType: row.target_type,
49	    targetId: row.target_id,
50	    targetLabel: row.target_label,
51	    createdAt: row.created_at,
52	    details,
53	  };
54	}
