      if (error instanceof ApiError && error.status === 409) {
        toast.error(t("undo-conflict"));
      } else if (error instanceof ApiError && error.status === 422) {
        toast.error(t("undo-invalid"));
      } else {
        toast.error(t("undo-error"));
      }
    } finally {
      setUndoing(false);
    }
  };

  return (

